export function retry<T>(configOrCount: number | RetryConfig = Infinity): MonoTypeOperatorFunction<T> {
  let config: RetryConfig;
  if (configOrCount && typeof configOrCount === 'object') {
    config = configOrCount;
  } else {
    config = {
      count: configOrCount
    };
  }
  const { count, resetOnSuccess = false } = config;

  return (source: Observable<T>) => count <= 0 ? EMPTY: lift(source, function (this: Subscriber<T>, source: Observable<T>) {
    const subscriber = this;
    let soFar = 0;
    const subscription = new Subscription();
    let innerSub: Subscription | null;
    const subscribeForRetry = () => {
      let syncUnsub = false;
      innerSub = source.subscribe({
        next: (value) => {
          if (resetOnSuccess) {
            soFar = 0;
          }
          subscriber.next(value);
        },
        error: (err) => {
          if (soFar++ < count) {
            if (innerSub) {
              innerSub.unsubscribe();
              innerSub = null;
              subscribeForRetry();
            } else {
              syncUnsub = true;
            }
          } else {
            subscriber.error(err);
          }
        },
        complete: () => subscriber.complete(),
      });
      if (syncUnsub) {
        innerSub.unsubscribe();
        innerSub = null;
        subscribeForRetry();
      } else {
        subscription.add(innerSub);
      }
    };
    subscribeForRetry();
    return subscription;
  })
}
